static constexpr const char* PROBE_TOOL = "VOX RDR2 RPF8 Recursive Content Probe";
static constexpr const char* PROBE_VERSION = "0.6.0";

struct EntryMeta { uint32_t hash{}; uint8_t encCfg{},encKey{},extId{}; bool resource{},sig{},dir{}; uint8_t comp{}; uint64_t disk{},off{},logical{}; uint32_t vf{},pf{}; };
static EntryMeta ParseEntry(const uint8_t* p){ EntryMeta e; uint64_t q0=U64LE(p),q8=U64LE(p+8),q10=U64LE(p+16); e.hash=(uint32_t)q0;e.encCfg=(uint8_t)(q0>>32);e.encKey=(uint8_t)(q0>>40);e.extId=(uint8_t)(q0>>48);e.resource=((q0>>56)&1)!=0;e.sig=((q0>>57)&1)!=0;e.dir=e.extId==0xFE;e.comp=(uint8_t)(q8>>59);e.disk=(q8&0x0FFFFFFFull)<<4;e.off=((q8>>28)&0x7FFFFFFFull)<<4;e.vf=(uint32_t)q10;e.pf=(uint32_t)(q10>>32);e.logical=e.dir?0:(e.resource?((q10&0xFFFFFFF0ull)+((q10>>32)&0xFFFFFFF0ull)):q10);return e; }
static std::string HashName(const EntryMeta&e,char p){std::ostringstream s;s<<std::uppercase<<std::hex<<std::setw(8)<<std::setfill('0')<<e.hash<<"."<<ExtFor(e.extId,p);return s.str();}

static std::vector<std::pair<uint64_t,uint64_t>> CipherRanges(uint8_t config,uint64_t fileSize,uint64_t chunkSize){std::vector<std::pair<uint64_t,uint64_t>>out;uint64_t cursor=0;auto add=[&](uint64_t a,uint64_t b){a=std::max(a,cursor);b=std::min(b,fileSize);if(a<b){out.push_back({a,b});cursor=b;}};uint64_t tailLen=0x400,tailOff=fileSize>tailLen?fileSize-tailLen:0,head=0,block=0,stride=0;if(uint8_t hc=config&3)head=uint64_t(0x400)<<(hc*2);if(uint8_t lc=(config>>2)&7){uint8_t sc=(config>>5)&7;block=uint64_t(0x400)<<lc;stride=uint64_t(sc+1)<<16;}add(0,head);if(head<tailOff){if(block||stride){if((stride==chunkSize)&&(tailOff<stride)&&(stride<fileSize))cursor=stride;else for(uint64_t b=cursor?stride:0;b+block<=tailOff&&stride;b+=stride)add(b,b+block);}add(tailOff,fileSize);}return out;}
static void DecryptCbcSlice(const Tfit2Context&c,const Tfit2Key&k,uint8_t iv[16],uint8_t*p,size_t n){for(size_t b=0;b<n/16;b++){uint8_t ct[16],pt[16];std::memcpy(ct,p+b*16,16);DecryptBlock(c,k,ct,pt);for(int i=0;i<16;i++)pt[i]^=iv[i];std::memcpy(p+b*16,pt,16);std::memcpy(iv,ct,16);}}
static void ApplyStridedDecryptPrefix(const Tfit2Context&c,const Tfit2Key&k,const uint8_t iv0[16],uint8_t cfg,uint64_t fullSize,uint64_t chunkSize,std::vector<uint8_t>&bytes){uint8_t iv[16];std::memcpy(iv,iv0,16);for(auto[a,b]:CipherRanges(cfg,fullSize,chunkSize)){if(a>=bytes.size())break;uint64_t ee=std::min<uint64_t>(b,bytes.size());if(ee<=a)continue;size_t n=(size_t)(ee-a);n-=n%16;if(n)DecryptCbcSlice(c,k,iv,bytes.data()+a,n);if(ee<b)break;}}

#define OODLE_BLOCK_LEN (1<<18)
#define OODLE_BLOCK_MAX (OODLE_BLOCK_LEN+128)
struct OodleSomeOut{uint32_t decodedCount,compBufUsed,curQuantumRawLen,curQuantumCompLen;};
struct OodleApi{HMODULE mod{};int(__stdcall*MemorySize)(int,intptr_t){};void*(__stdcall*Create)(int,long long,void*,size_t){};int(__stdcall*Reset)(void*,intptr_t,intptr_t){};void(__stdcall*Destroy)(void*){};int(__stdcall*DecodeSome)(void*,OodleSomeOut*,void*,intptr_t,intptr_t,intptr_t,const void*,intptr_t,int,int,int,int){};};
static bool LoadOodle(const fs::path&root,OodleApi&a,std::string&used){std::vector<fs::path>cand;try{for(auto&de:fs::directory_iterator(root)){if(!de.is_regular_file())continue;auto n=de.path().filename().string();std::string l=n;std::transform(l.begin(),l.end(),l.begin(),[](unsigned char c){return(char)std::tolower(c);});if(l.rfind("oo2core_",0)==0&&l.find("_win64.dll")!=std::string::npos)cand.push_back(de.path());}}catch(...){}std::sort(cand.rbegin(),cand.rend());for(auto&p:cand){HMODULE m=LoadLibraryW(p.c_str());if(!m)continue;a.mod=m;a.MemorySize=(decltype(a.MemorySize))GetProcAddress(m,"OodleLZDecoder_MemorySizeNeeded");a.Create=(decltype(a.Create))GetProcAddress(m,"OodleLZDecoder_Create");a.Reset=(decltype(a.Reset))GetProcAddress(m,"OodleLZDecoder_Reset");a.Destroy=(decltype(a.Destroy))GetProcAddress(m,"OodleLZDecoder_Destroy");a.DecodeSome=(decltype(a.DecodeSome))GetProcAddress(m,"OodleLZDecoder_DecodeSome");if(a.MemorySize&&a.Create&&a.Reset&&a.Destroy&&a.DecodeSome){used=p.filename().string();return true;}FreeLibrary(m);a={};}return false;}
static bool OodleDecodePrefix(OodleApi&a,const std::vector<uint8_t>&input,uint64_t realSize,size_t want,std::vector<uint8_t>&output,std::string&err){want=(size_t)std::min<uint64_t>(want,realSize);output.clear();output.reserve(want);if(!want)return true;int mem=a.MemorySize(-1,-1);if(mem<=0){err="oodle_memory_size";return false;}std::vector<uint8_t>state((size_t)mem);void*dec=a.Create(-1,(long long)realSize,state.data(),state.size());if(!dec){err="oodle_create";return false;}a.Reset(dec,0,0);std::vector<uint8_t>bin(OODLE_BLOCK_MAX),bout(OODLE_BLOCK_LEN);size_t inPos=0,buffered=0,needed=0,outStart=0,outEnd=0,total=0;bool ok=true;for(size_t guard=0;guard<200000&&total<want;guard++){if(outEnd>outStart){size_t n=std::min(want-total,outEnd-outStart);output.insert(output.end(),bout.begin()+outStart,bout.begin()+outStart+n);outStart+=n;total+=n;if(total>=want)break;if(outStart<outEnd)continue;if(outEnd==OODLE_BLOCK_LEN)outStart=outEnd=0;}if(buffered<needed){size_t take=std::min(needed-buffered,input.size()-std::min(inPos,input.size()));if(take){std::memcpy(bin.data()+buffered,input.data()+inPos,take);buffered+=take;inPos+=take;}if(buffered<needed&&inPos>=input.size()){err="oodle_input_prefix_exhausted";ok=false;break;}}if(buffered==0){needed=16;if(inPos>=input.size()){err="oodle_no_input";ok=false;break;}continue;}OodleSomeOut r{};int rc=a.DecodeSome(dec,&r,bout.data(),(intptr_t)outEnd,(intptr_t)realSize,(intptr_t)(bout.size()-outEnd),bin.data(),(intptr_t)buffered,0,1,0,3);if(rc<=0){err="oodle_decode";ok=false;break;}if(r.compBufUsed){if(r.compBufUsed>buffered){err="oodle_used_overflow";ok=false;break;}size_t extra=buffered-r.compBufUsed;if(extra)std::memmove(bin.data(),bin.data()+r.compBufUsed,extra);buffered=extra;}needed=buffered;if(r.decodedCount){outEnd+=r.decodedCount;if(outEnd>bout.size()){err="oodle_output_overflow";ok=false;break;}}else{if(r.curQuantumRawLen&&outEnd+r.curQuantumRawLen>bout.size()){err="oodle_quantum_raw";ok=false;break;}if(r.curQuantumCompLen){if(r.curQuantumCompLen>bin.size()){err="oodle_quantum_comp";ok=false;break;}needed=std::max<size_t>(needed,r.curQuantumCompLen);}}needed=std::min<size_t>(needed+16,bin.size());if(buffered<needed&&inPos<input.size()){size_t take=std::min(needed-buffered,input.size()-inPos);std::memcpy(bin.data()+buffered,input.data()+inPos,take);buffered+=take;inPos+=take;}}a.Destroy(dec);return ok&&output.size()>=want;}

static std::vector<uint8_t> ReadEntryPrefixFile(const fs::path&file,uint64_t fileSize,const EntryMeta&e,const Tfit2Context&ctx,const std::map<uint16_t,Tfit2Key>&keys,const uint8_t iv[16],OodleApi*oodle,size_t want,std::string&status){if(e.dir||!e.logical){status="empty";return{};}uint64_t raw=e.disk,off=e.off;if(e.sig){if(raw<0x100){status="bad_signature_size";return{};}raw-=0x100;}if(e.resource){if(raw<16){status="bad_resource_size";return{};}off+=16;raw-=16;}uint64_t streamLen=e.comp?raw:e.logical;if(off>=fileSize){status="out_of_bounds";return{};}size_t rawCap=(size_t)std::min<uint64_t>(streamLen,64ull*1024*1024);rawCap=(size_t)std::min<uint64_t>(rawCap,fileSize-off);auto b=ReadBytes(file,off,rawCap);if(e.encKey!=0xFF){auto it=keys.find(e.encKey);if(it==keys.end()){status="missing_entry_key";return{};}uint64_t chunk=e.resource?(e.comp?0x80000:e.logical):(e.comp?0x2000:0x1000);ApplyStridedDecryptPrefix(ctx,it->second,iv,e.encCfg,streamLen,chunk,b);}if(e.comp==0){if(b.size()>want)b.resize(want);status="ok_uncompressed";return b;}if(e.comp==2){if(!oodle){status="oodle_unavailable";return{};}std::vector<uint8_t>out;std::string er;if(!OodleDecodePrefix(*oodle,b,e.logical,want,out,er)){status=er;return out;}status="ok_oodle";return out;}status="unsupported_compressor_"+std::to_string(e.comp);return{};}
static bool ParseRpfTocPrefix(std::vector<uint8_t>&prefix,const Tfit2Context&ctx,const std::map<uint16_t,Tfit2Key>&keys,const uint8_t iv[16],uint16_t&platform,uint16_t&tag,std::vector<EntryMeta>&entries,std::string&status){if(prefix.size()<16||std::memcmp(prefix.data(),"8FPR",4)!=0){status="not_rpf8";return false;}uint32_t n=U32LE(prefix.data()+4);std::memcpy(&tag,prefix.data()+12,2);std::memcpy(&platform,prefix.data()+14,2);uint64_t need=TOC_OFFSET+(uint64_t)n*24;if(n>1000000||need>prefix.size()){status="toc_prefix_too_short";return false;}std::vector<uint8_t>toc(prefix.begin()+TOC_OFFSET,prefix.begin()+need);if(tag!=0xFF){auto it=keys.find(tag);if(it==keys.end()){status="missing_toc_key";return false;}DecryptCbc(ctx,it->second,iv,toc);}entries.reserve(n);for(uint32_t i=0;i<n;i++)entries.push_back(ParseEntry(toc.data()+i*24));status="ok";return true;}
static std::string FirstMagic(const std::vector<uint8_t>&b){if(b.size()<4)return"";bool p=true;for(int i=0;i<4;i++)if(b[i]<32||b[i]>126)p=false;if(p)return std::string((const char*)b.data(),4);std::ostringstream s;s<<"0x"<<std::hex<<std::setfill('0');for(int i=0;i<4;i++)s<<std::setw(2)<<(int)b[i];return s.str();}
static std::vector<std::string> KeywordHits(const std::vector<uint8_t>&b){static const std::vector<std::string>kw={"greet","antagon","threat","rob","defus","melee","grapple","combat","locom","door","scenario","interact","prompt","ped","weapon","ragdoll","physics","cover","ambient","gesture","conversation"};std::vector<std::string>hits;std::string cur;auto flush=[&](){if(cur.size()>=5){std::string l=cur;std::transform(l.begin(),l.end(),l.begin(),[](unsigned char c){return(char)std::tolower(c);});for(auto&k:kw)if(l.find(k)!=std::string::npos){hits.push_back(cur.substr(0,160));break;}}cur.clear();};for(uint8_t x:b){if(x>=32&&x<=126){if(cur.size()<300)cur.push_back((char)x);}else flush();if(hits.size()>=40)break;}flush();return hits;}
static int ExtPriority(const std::string&e){if(e=="ycd")return100;if(e=="yas")return96;if(e=="ymt")return90;if(e=="yed")return88;if(e=="ypt")return82;if(e=="ymap"||e=="ytyp")return78;if(e=="yad"||e=="yld")return75;if(e=="rpf")return55;if(e=="bin")return25;return40;}
static bool ProbeSelfTest(){EntryMeta e{};e.hash=0x12345678;e.extId=67;if(ExtFor(e.extId,'y')!="ycd")return false;std::vector<uint8_t>r(TOC_OFFSET+24);std::memcpy(r.data(),"8FPR",4);uint32_t n=1;std::memcpy(r.data()+4,&n,4);uint16_t tag=0xFF,plat='y';std::memcpy(r.data()+12,&tag,2);std::memcpy(r.data()+14,&plat,2);uint64_t q0=e.hash|(uint64_t(0xFF)<<40)|(uint64_t(67)<<48)|(1ull<<56);std::memcpy(r.data()+TOC_OFFSET,&q0,8);std::vector<EntryMeta>out;uint16_t p=0,t=0;std::string st;auto cp=std::make_unique<Tfit2Context>();std::map<uint16_t,Tfit2Key>keys;uint8_t iv[16]{};bool ok=ParseRpfTocPrefix(r,*cp,keys,iv,p,t,out,st)&&out.size()==1&&ExtFor(out[0].extId,'y')=="ycd";std::cout<<(ok?"[SELFTEST] recursive RPF8 TOC probe OK\n":"[SELFTEST] recursive RPF8 TOC probe FAILED\n");return ok;}

int wmain(int argc,wchar_t**argv){try{if(HasArg(argc,argv,L"--self-test"))return(SelfTest()&&ProbeSelfTest())?0:2;fs::path root=FindArg(argc,argv,L"--root"),hashes=FindArg(argc,argv,L"--fingerprints"),rpf8src=FindArg(argc,argv,L"--rpf8-source");if(HasArg(argc,argv,L"--fingerprint-self-test")){if(hashes.empty()||rpf8src.empty())throw std::runtime_error("fingerprint inputs required");return FingerprintSelfTest(hashes,rpf8src)?0:2;}fs::path out=FindArg(argc,argv,L"--out");if(out.empty())out=fs::current_path()/"VOX-RDR2-RPF8-Content-Probe";if(root.empty()||hashes.empty()||rpf8src.empty())throw std::runtime_error("Usage: --root <RDR2> --fingerprints <RDR2.h> --rpf8-source <rpf8.cpp>");if(!fs::is_regular_file(root/"RDR2.exe"))throw std::runtime_error("RDR2.exe not found");fs::create_directories(out);
std::string htxt=ReadText(hashes),ctxt=ReadText(rpf8src);auto keyfps=QuotedStrings(ExtractInitializerBody(htxt,"RDR2_PC_KEY_HASHES[166]"));auto ctxfps=QuotedStrings(ExtractInitializerBody(htxt,"RDR2_PC_TFIT2_HASHES"));std::string ivfp=ParseIvFingerprint(ctxt);if(keyfps.size()!=166||ctxfps.size()!=565)throw std::runtime_error("fingerprint schema mismatch");std::vector<SecretSpec>specs;std::map<uint16_t,size_t>keySpec;for(uint16_t i=0;i<163;i++){keySpec[i]=specs.size();AddSpec(specs,"key_"+Hex(i,2),keyfps[i],sizeof(Tfit2Key));}for(auto[tag,idx]:std::vector<std::pair<uint16_t,int>>{{0xC0,163},{0xC5,164},{0xC6,165}}){keySpec[tag]=specs.size();AddSpec(specs,"key_"+Hex(tag,2),keyfps[idx],sizeof(Tfit2Key));}size_t ctxStart=specs.size(),c=0;AddSpec(specs,"ctx_init",ctxfps[c++],sizeof(((Tfit2Context*)0)->init));for(int r=0;r<17;r++){AddSpec(specs,"ctx_lookup",ctxfps[c++],sizeof(((Tfit2Context*)0)->rounds[0].lookup));for(int b=0;b<16;b++){AddSpec(specs,"ctx_masks",ctxfps[c++],sizeof(((Tfit2Context*)0)->rounds[0].blocks[0].masks));AddSpec(specs,"ctx_xor",ctxfps[c++],4);}}AddSpec(specs,"ctx_end_masks",ctxfps[c++],sizeof(((Tfit2Context*)0)->endMasks));AddSpec(specs,"ctx_end_tables",ctxfps[c++],sizeof(((Tfit2Context*)0)->endTables));AddSpec(specs,"ctx_end_xor",ctxfps[c++],sizeof(((Tfit2Context*)0)->endXor));size_t ivSpec=specs.size();AddSpec(specs,"iv",ivfp,16);
DWORD pid=FindProcessId(L"RDR2.exe");if(!pid)throw std::runtime_error("RDR2.exe is not running");HANDLE proc=OpenProcess(PROCESS_QUERY_INFORMATION|PROCESS_VM_READ,FALSE,pid);if(!proc)throw std::runtime_error("Cannot open RDR2 memory read-only; run as administrator");std::cout<<"[MEM] Discovering all PC RPF8 entry keys/context...\n";bool discovered=DiscoverSecrets(proc,specs);CloseHandle(proc);if(!discovered)throw std::runtime_error("TFIT2 discovery incomplete: "+std::to_string(FoundCount(specs))+"/"+std::to_string(specs.size()));auto ctxp=std::make_unique<Tfit2Context>();Tfit2Context&ctx=*ctxp;size_t si=ctxStart;CopyExact(ctx.init,sizeof(ctx.init),specs[si++]);for(int r=0;r<17;r++){CopyExact(ctx.rounds[r].lookup,sizeof(ctx.rounds[r].lookup),specs[si++]);for(int b=0;b<16;b++){CopyExact(ctx.rounds[r].blocks[b].masks,sizeof(ctx.rounds[r].blocks[b].masks),specs[si++]);CopyExact(&ctx.rounds[r].blocks[b].xorr,4,specs[si++]);}}CopyExact(ctx.endMasks,sizeof(ctx.endMasks),specs[si++]);CopyExact(ctx.endTables,sizeof(ctx.endTables),specs[si++]);CopyExact(ctx.endXor,sizeof(ctx.endXor),specs[si++]);uint8_t iv[16];CopyExact(iv,16,specs[ivSpec]);std::map<uint16_t,Tfit2Key>keys;for(auto&[tag,idx]:keySpec){Tfit2Key k{};CopyExact(&k,sizeof(k),specs[idx]);keys[tag]=k;}
OodleApi oa;std::string oodleName;bool oodleOk=LoadOodle(root,oa,oodleName);std::cout<<"[OODLE] "<<(oodleOk?"loaded "+oodleName:"not found; Oodle entries will be skipped")<<"\n";std::ofstream nested(out/"CONTENT-nested-entries.csv",std::ios::binary),direct(out/"CONTENT-direct-probes.csv",std::ios::binary),hits(out/"CONTENT-keyword-hits.csv",std::ios::binary),prio(out/"CONTENT-priority-candidates.csv",std::ios::binary);nested<<"outer_archive,outer_index,outer_name,nested_index,hash_hex,extension,generated_name,enc_key,enc_config,compressor,logical_size,on_disk_size,is_resource\n";direct<<"archive,index,generated_name,extension,status,magic,logical_size,prefix_bytes,keyword_hit_count\n";hits<<"archive,index,generated_name,hit\n";prio<<"score,archive,index,generated_name,extension,source,keyword_hits\n";uint64_t outerCount=0,nestedArchives=0,nestedEntries=0,ycd=0,yas=0,ymt=0,directOk=0,keywordCount=0;std::vector<std::tuple<int,std::string,uint32_t,std::string,std::string,int>>priorities;
for(auto&rel:DefaultTargets()){ArchiveInfo a=ReadArchiveHeader(root,rel);auto toc=ReadBytes(a.full,TOC_OFFSET,(size_t)a.entryCount*24);if(a.tag!=0xFF)DecryptCbc(ctx,keys.at(a.tag),iv,toc);char platform=(char)(a.platform&0xFF);std::cout<<"[ARCHIVE] "<<rel<<" entries="<<a.entryCount<<"\n";for(uint32_t i=0;i<a.entryCount;i++){outerCount++;EntryMeta e=ParseEntry(toc.data()+i*24);std::string ext=ExtFor(e.extId,platform),name=HashName(e,platform);size_t want=(ext=="rpf")?16ull*1024*1024:512ull*1024;std::string st;auto pref=ReadEntryPrefixFile(a.full,a.size,e,ctx,keys,iv,oodleOk?&oa:nullptr,want,st);auto kh=KeywordHits(pref);if(st.rfind("ok_",0)==0)directOk++;keywordCount+=kh.size();direct<<Csv(rel)<<","<<i<<","<<name<<","<<ext<<","<<st<<","<<Csv(FirstMagic(pref))<<","<<e.logical<<","<<pref.size()<<","<<kh.size()<<"\n";for(auto&s:kh)hits<<Csv(rel)<<","<<i<<","<<name<<","<<Csv(s)<<"\n";int sc=ExtPriority(ext)+(int)std::min<size_t>(30,kh.size()*6);if(ext!="bin"||!kh.empty())priorities.push_back({sc,rel,i,name,ext,(int)kh.size()});if(pref.size()>=16&&std::memcmp(pref.data(),"8FPR",4)==0){uint16_t np=0,nt=0;std::vector<EntryMeta>ne;std::string ps;if(ParseRpfTocPrefix(pref,ctx,keys,iv,np,nt,ne,ps)){nestedArchives++;char nplat=(char)(np&0xFF);for(uint32_t j=0;j<ne.size();j++){auto&x=ne[j];std::string xe=ExtFor(x.extId,nplat),xn=HashName(x,nplat);nested<<Csv(rel)<<","<<i<<","<<name<<","<<j<<","<<Hex(x.hash,8)<<","<<xe<<","<<xn<<","<<(int)x.encKey<<","<<(int)x.encCfg<<","<<(int)x.comp<<","<<x.logical<<","<<x.disk<<","<<(x.resource?"true":"false")<<"\n";nestedEntries++;if(xe=="ycd")ycd++;if(xe=="yas")yas++;if(xe=="ymt")ymt++;priorities.push_back({ExtPriority(xe)+25,rel,i,xn,xe,0});}}}}}
std::sort(priorities.begin(),priorities.end(),[](auto&a,auto&b){return std::get<0>(a)>std::get<0>(b);});for(size_t i=0;i<std::min<size_t>(priorities.size(),2000);i++){auto&x=priorities[i];prio<<std::get<0>(x)<<","<<Csv(std::get<1>(x))<<","<<std::get<2>(x)<<","<<std::get<3>(x)<<","<<std::get<4>(x)<<","<<(std::get<4>(x)=="rpf"?"outer_or_nested":"asset")<<","<<std::get<5>(x)<<"\n";}nested.close();direct.close();hits.close();prio.close();if(oa.mod)FreeLibrary(oa.mod);std::ofstream js(out/"CONTENT-summary.json",std::ios::binary);js<<"{\n  \"tool\":\""<<PROBE_TOOL<<"\",\n  \"version\":\""<<PROBE_VERSION<<"\",\n  \"read_only\":true,\n  \"raw_assets_written\":false,\n  \"secrets_written\":false,\n  \"secrets_found\":"<<FoundCount(specs)<<",\n  \"secrets_required\":"<<specs.size()<<",\n  \"oodle_loaded\":"<<(oodleOk?"true":"false")<<",\n  \"oodle_library\":\""<<Json(oodleName)<<"\",\n  \"outer_entries_probed\":"<<outerCount<<",\n  \"direct_prefix_ok\":"<<directOk<<",\n  \"nested_archives_opened\":"<<nestedArchives<<",\n  \"nested_entries_enumerated\":"<<nestedEntries<<",\n  \"nested_ycd\":"<<ycd<<",\n  \"nested_yas\":"<<yas<<",\n  \"nested_ymt\":"<<ymt<<",\n  \"keyword_hits\":"<<keywordCount<<"\n}\n";js.close();std::ofstream rp(out/"CONTENT-report.txt",std::ios::binary);rp<<PROBE_TOOL<<" v"<<PROBE_VERSION<<"\nREAD-ONLY / no raw asset output\nSecrets: "<<FoundCount(specs)<<"/"<<specs.size()<<"\nOodle: "<<(oodleOk?oodleName:"unavailable")<<"\nOuter entries probed: "<<outerCount<<"\nDirect prefix OK: "<<directOk<<"\nNested RPF8 opened: "<<nestedArchives<<"\nNested entries enumerated: "<<nestedEntries<<"\nNested ycd: "<<ycd<<" | yas: "<<yas<<" | ymt: "<<ymt<<"\nKeyword hits: "<<keywordCount<<"\n";rp.close();std::cout<<"[OK] Probe complete: nested="<<nestedArchives<<" entries="<<nestedEntries<<" ycd="<<ycd<<" yas="<<yas<<" ymt="<<ymt<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"[ERROR] "<<e.what()<<"\n";return 1;}}
